/* icon_pack.h — the Oxygen icon pack, passed by the boot loader as a module and
 * generated by tools/gen-oxygen-icons.py (see assets/oxygen/README.md for the license). */
#ifndef HELIX_ICON_PACK_H
#define HELIX_ICON_PACK_H

#include <stddef.h>
#include <stdint.h>

/* One 32x32 icon: 4096 bytes, B G R A per pixel, row-major, straight alpha. */
#define ICON32_BYTES 4096u

/* Called once at boot with the module the loader passed in. */
void icon_pack_set(const void *data, size_t size);

/* Pixels of the named icon, or NULL when the pack is missing, malformed, or lacks it. */
const uint8_t *icon_pack_find(const char *name);

#endif /* HELIX_ICON_PACK_H */
